// @vegastack date-picker@0.60.0 sha256-Mpr/bePvSLChAWOBfjRfOLx6x6i7aTkHRYre+5P+oF0=

"use client";

import * as React from "react";
import {
  DEFAULT_LOCALE,
  formatCalendarDate,
  formatDateTime,
  formatTimeValue,
  fromZoned,
  localeHourCycle,
  parseCalendarDay,
  parseTimeOfDay,
  toCalendarDay,
  zonedParts,
  zonedToday,
  type DateFormat,
  type TimeHourCycle,
} from "@/lib/date-time";
import type { DateRange, DayButton, Matcher } from "react-day-picker";
import {
  Calendar as CalendarIcon,
  CalendarClock,
  CheckIcon,
  X,
} from "lucide-react";
import { Field as FieldPrimitive } from "@base-ui/react/field";
import { cn, mergeRefs } from "@vegastack/design";
import { Button } from "@/components/ui/button";
import type { Calendar } from "@/components/ui/calendar";
import {
  Popover,
  PopoverTrigger,
  PopoverContent,
} from "@/components/ui/popover";
import { Input } from "@/components/ui/input";
import { useDateFormat, useTimeZone } from "@/components/ui/relative-time";
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group";

/* ------------------------------------------------------------------------------------------------
 * DatePicker — single-date and range date selection, composed from upstream `Calendar`, `Popover`
 * and `Button`. The calendar itself is NOT ours: `@/components/ui/calendar` is shadcn's file plus
 * its patch, and this module imports it rather than restating a single one of its class strings.
 *
 * Three exports:
 *  - `DatePicker`      — single date; upstream `Calendar` inside a `Popover` triggered by a `Button`
 *                        that shows the formatted date. Optional quick presets (Today / Tomorrow).
 *  - `DateTimePicker`  — a date and a time of day in the same popup: the calendar beside a typed
 *                        time over the day's times, editing an instant on the reader's clock.
 *  - `DateRangePicker` — the same, for a `{ from, to }` range across two months.
 *
 * Formatting uses the native `Intl.DateTimeFormat` (NO date-fns) so there is no extra runtime dep.
 * `react-day-picker` survives here as TYPES plus its two matcher evaluators — see the note on
 * `isDateDisabled` for why the preset gate must read the calendar's own matcher and not a
 * re-derived copy of it. Nothing in this file renders a day, a month or a caption.
 *
 * The calendar engine (`react-day-picker` + `date-fns`) is LOADED LAZILY: it is fetched when the
 * trigger is hovered or focused and rendered only once the popup opens, so a page that shows a
 * picker never ships the calendar in its first bundle. The popup's body waits for it (a few ms
 * after a hover prefetch), and nothing else changes.
 * ----------------------------------------------------------------------------------------------*/

/* ------------------------------------------------------------------------------------------------
 * The lazily loaded calendar engine
 * ----------------------------------------------------------------------------------------------*/

interface CalendarParts {
  Calendar: typeof import("@/components/ui/calendar").Calendar;
  CalendarDayButton: typeof import("@/components/ui/calendar").CalendarDayButton;
  dateMatchModifiers: typeof import("react-day-picker").dateMatchModifiers;
  rangeContainsModifiers: typeof import("react-day-picker").rangeContainsModifiers;
}

/** Set once the engine has loaded; every reader below runs inside `CalendarReady`, after that. */
let calendarParts: CalendarParts | undefined;
let calendarLoad: Promise<CalendarParts> | undefined;

/** Fetch the calendar engine once. Safe to call on every hover and focus; a failed load retries. */
function loadCalendar(): Promise<CalendarParts> {
  calendarLoad ??= Promise.all([
    import("@/components/ui/calendar"),
    import("react-day-picker"),
  ]).then(
    ([calendar, dayPicker]) =>
      (calendarParts = {
        Calendar: calendar.Calendar,
        CalendarDayButton: calendar.CalendarDayButton,
        dateMatchModifiers: dayPicker.dateMatchModifiers,
        rangeContainsModifiers: dayPicker.rangeContainsModifiers,
      }),
    (error: unknown) => {
      calendarLoad = undefined;
      throw error;
    },
  );
  return calendarLoad;
}

function prefetchCalendar() {
  void loadCalendar().catch(() => {});
}

/** Renders its children (a render function) once the engine has loaded. */
const CalendarReady = React.lazy(() =>
  loadCalendar().then((parts) => ({
    default: ({
      children,
    }: {
      children: (parts: CalendarParts) => React.ReactNode;
    }) => children(parts),
  })),
);

/** The popup's body: the preset rail and the calendar, once the engine is there. */
function CalendarBody({
  children,
}: {
  children: (parts: CalendarParts) => React.ReactNode;
}) {
  return (
    <React.Suspense fallback={null}>
      <CalendarReady>{children}</CalendarReady>
    </React.Suspense>
  );
}

/* ------------------------------------------------------------------------------------------------
 * Formatting helpers (native Intl — no date-fns)
 * ----------------------------------------------------------------------------------------------*/

/** Default single-date display format: e.g. "Jun 21, 2026". */
const DEFAULT_TRIGGER_FORMAT: Intl.DateTimeFormatOptions = {
  year: "numeric",
  month: "short",
  day: "numeric",
};

/**
 * Format a single date with `Intl.DateTimeFormat`, or — for the default face under a
 * `TimeZoneProvider` `dateFormat` — in the workspace's order ("12 Nov 2026", "2026-11-12").
 */
function formatDate(
  date: Date,
  options: Intl.DateTimeFormatOptions,
  locale?: string,
  dateFormat?: DateFormat,
): string {
  if (dateFormat && options === DEFAULT_TRIGGER_FORMAT)
    return formatCalendarDate(toCalendarDay(date), { dateFormat });
  return new Intl.DateTimeFormat(locale ?? DEFAULT_LOCALE, options).format(
    date,
  );
}

/** Format a `{ from, to }` range, collapsing to a single date when `to` is absent. */
function formatRange(
  range: DateRange,
  options: Intl.DateTimeFormatOptions,
  locale?: string,
  dateFormat?: DateFormat,
): string {
  if (!range.from) return "";
  const one = (date: Date) => formatDate(date, options, locale, dateFormat);
  if (!range.to) return one(range.from);
  return `${one(range.from)} – ${one(range.to)}`;
}

/* ------------------------------------------------------------------------------------------------
 * The calendar inside the popover
 * ----------------------------------------------------------------------------------------------*/

/**
 * Props forwarded to the inner upstream `Calendar` — every `DayPicker` knob (`timeZone`, `locale`,
 * `footer`, `captionLayout`, `startMonth`, `endMonth`, `labels`, `formatters`, …) minus the four
 * the picker owns.
 */
type ForwardedCalendarProps = Omit<
  React.ComponentProps<typeof Calendar>,
  "mode" | "selected" | "onSelect" | "disabled"
>;

/**
 * The day button, wrapping — never copying — upstream's `CalendarDayButton`, for one reason: the
 * focus call.
 *
 * Upstream's own `focused` effect is a plain `.focus()`. With `autoFocus` (this picker's default)
 * it fires on the calendar's first paint, while the portaled popup is still UNPOSITIONED at the
 * document's top-left, so the browser scrolls the page up to that pre-position spot every time a
 * below-the-fold trigger opens the picker. Handing upstream `focused: false` stops its effect from
 * running at all and this one focuses with `preventScroll`, which loses nothing: the popup is
 * fixed-positioned, and keyboard focus still lands on the day. `focused` drives no styling here —
 * the `group-data-[focused=true]/day` selector upstream's button carries reads the attribute
 * react-day-picker writes on the parent cell, which is untouched.
 *
 * Inline (an internal part, not an export) because the reason is the popover's, not the calendar's:
 * the inline `<Calendar>` upstream documents has no unpositioned first paint and needs none of it.
 */
function PopoverDayButton({
  modifiers,
  ...props
}: React.ComponentProps<typeof DayButton>) {
  const ref = React.useRef<HTMLButtonElement>(null);
  React.useEffect(() => {
    if (modifiers.focused) ref.current?.focus({ preventScroll: true });
  }, [modifiers.focused]);
  // Rendered only by the calendar, so the engine is loaded.
  const DayButton = calendarParts!.CalendarDayButton as DayButtonWithRef;

  return (
    <DayButton
      ref={ref}
      modifiers={{ ...modifiers, focused: false }}
      {...props}
      // Upstream's `dark:hover:text-foreground` would paint a chosen day's label in the light
      // foreground over the light primary fill, where it vanishes: a filled day keeps its
      // primary-foreground ink on hover. `dark:` too, so the attribute outranks upstream's rule.
      className={cn(
        "dark:data-[range-end=true]:hover:text-primary-foreground dark:data-[range-start=true]:hover:text-primary-foreground dark:data-[selected-single=true]:hover:text-primary-foreground",
        props.className,
      )}
    />
  );
}

/**
 * The one widening this file performs, and it adds nothing the runtime does not already do: React
 * 19 hands a function component its `ref` as an ordinary prop, and upstream's `CalendarDayButton`
 * spreads its rest props onto Base UI's `Button`, so the ref reaches the DOM button. Its prop type
 * is react-day-picker's `DayButton`, written against `ButtonHTMLAttributes`, which has no `ref`
 * member — so the type, not the behaviour, is what is missing.
 */
type DayButtonWithRef = (
  props: React.ComponentProps<CalendarParts["CalendarDayButton"]> & {
    ref?: React.Ref<HTMLButtonElement>;
  },
) => React.ReactNode;

/** The `components` override every picker hands its calendar. */
const POPOVER_CALENDAR_COMPONENTS = { DayButton: PopoverDayButton } as const;

/* ------------------------------------------------------------------------------------------------
 * Presets
 * ----------------------------------------------------------------------------------------------*/

/** A quick-select preset for the single `DatePicker` — a label and the date it applies. */
export interface DatePreset {
  /** Button text, e.g. "Today". */
  label: string;
  /** The date this preset selects. */
  date: Date;
}

/** A quick-select preset for the `DateRangePicker` — a label and the range it applies. */
export interface DateRangePreset {
  /** Button text, e.g. "Last 7 days". */
  label: string;
  /** The `{ from, to }` range this preset selects. */
  range: DateRange;
}

/** Strip the time component so two dates on the same day compare equal. */
function startOfDay(date: Date): Date {
  const d = new Date(date);
  d.setHours(0, 0, 0, 0);
  return d;
}

/** Shift a date by `n` days (negative = past). */
function addDays(date: Date, n: number): Date {
  const d = startOfDay(date);
  d.setDate(d.getDate() + n);
  return d;
}

/* ------------------------------------------------------------------------------------------------
 * Shared disabled-date predicates
 *
 * The calendar honors `disabledDates` via react-day-picker's `disabled` matcher. Presets must obey
 * the SAME policy, so we reuse react-day-picker's own matcher evaluators (`dateMatchModifiers` /
 * `rangeContainsModifiers`) rather than reimplementing the rule — that guarantees the preset gate
 * never drifts from what the calendar grid actually blocks.
 * ----------------------------------------------------------------------------------------------*/

/** True when `date` is blocked by the `disabledDates` matcher (same one the calendar applies). */
function isDateDisabled(
  date: Date,
  disabledDates: Matcher | Matcher[] | undefined,
): boolean {
  if (!disabledDates) return false;
  return calendarParts!.dateMatchModifiers(date, disabledDates);
}

/**
 * True when ANY day within `range` (endpoints and every day in between) is blocked by the
 * `disabledDates` matcher. An open-ended range (missing `from`/`to`) falls back to checking the
 * known endpoint so a half-built preset is still gated.
 */
function isRangeDisabled(
  range: DateRange | undefined,
  disabledDates: Matcher | Matcher[] | undefined,
): boolean {
  if (!disabledDates || !range) return false;
  if (range.from && range.to) {
    return calendarParts!.rangeContainsModifiers(
      { from: range.from, to: range.to },
      disabledDates,
    );
  }
  const endpoint = range.from ?? range.to;
  return endpoint
    ? calendarParts!.dateMatchModifiers(endpoint, disabledDates)
    : false;
}

/** Options for the default preset factories. */
export interface DatePresetOptions {
  /** IANA zone whose calendar day is "today" — pass `useTimeZone()`. @default the runtime zone */
  timeZone?: string;
}

/**
 * `defaultDatePresets` — Today / Tomorrow. Pass your own `presets` to override; this is a sensible
 * starting set for due-date style pickers. "Today" is the calendar day in `options.timeZone`.
 */
export function defaultDatePresets(
  now: Date = new Date(),
  options: DatePresetOptions = {},
): DatePreset[] {
  const today = zonedToday(now, options.timeZone);
  return [
    { label: "Today", date: today },
    { label: "Tomorrow", date: addDays(today, 1) },
  ];
}

/**
 * `defaultRangePresets` — Today / Last 7 days / Last 30 days. Pass your own `presets` to override.
 * "Today" is the calendar day in `options.timeZone`.
 */
export function defaultRangePresets(
  now: Date = new Date(),
  options: DatePresetOptions = {},
): DateRangePreset[] {
  const today = zonedToday(now, options.timeZone);
  return [
    { label: "Today", range: { from: today, to: today } },
    { label: "Last 7 days", range: { from: addDays(today, -6), to: today } },
    { label: "Last 30 days", range: { from: addDays(today, -29), to: today } },
  ];
}

/**
 * The day the grid marks as today: the provider zone's calendar day, computed when the popup
 * opens. A `calendarProps.today` or `calendarProps.timeZone` wins — the engine then decides.
 */
function useZonedToday(
  open: boolean,
  calendarProps: { today?: Date; timeZone?: string },
): Date | undefined {
  const zone = useTimeZone();
  const explicit = calendarProps.today;
  const engineZone = calendarProps.timeZone;
  return React.useMemo(
    () =>
      explicit ??
      (!open || engineZone || !zone ? undefined : zonedToday(Date.now(), zone)),
    [open, explicit, engineZone, zone],
  );
}

/**
 * The popup the pickers share. Upstream's `PopoverContent` is a padded `flex-col gap-2.5` card;
 * here it is a frameless host for the rail and the calendar, which own their padding. Without the
 * `gap-0` the popover's column gap would sit between them, and without an explicit `flex-row` for a
 * rail the popover's own `flex-col` wins the merge and the "inline-start" rail stacks ABOVE the
 * calendar at every width — which is how its `border-e` ended up drawn along the popup's own
 * edge, a doubled hairline, rather than between the two.
 */
const POPUP_CLASSES = "w-auto gap-0 p-0";

/**
 * The calendar inside the popup is transparent, so it reads as the popup's own surface. Upstream's
 * `calendar` does this itself for `in-data-[slot=popover-content]`, but the pickers rename the
 * popup `date-picker-content` / `date-range-picker-content` (their public hooks), so that selector
 * never matched and the calendar painted `bg-background` over `bg-popover` — two tones in dark.
 */
const POPUP_CALENDAR_CLASSES = "bg-transparent";

/** Shared preset-sidebar shell — an inline-start rail of `ghost` buttons inside the popover. */
function PresetRail({ children }: { children: React.ReactNode }) {
  return (
    <div
      data-slot="date-picker-presets"
      // The divider is drawn only on the side that FACES the calendar: `border-e` while the rail
      // sits at the inline start, `border-b` once it stacks above it. Below sm the rail becomes a
      // horizontally scrollable chip row — side-by-side rail+calendar exceeds the popup's
      // viewport-width clamp on narrow phones.
      className="flex shrink-0 flex-col gap-0.5 border-e border-border p-2 max-sm:flex-row max-sm:overflow-x-auto max-sm:border-e-0 max-sm:border-b"
    >
      {children}
    </div>
  );
}

/* ------------------------------------------------------------------------------------------------
 * DatePicker (single)
 * ----------------------------------------------------------------------------------------------*/

/** Props accepted by `DatePicker`. */
export interface DatePickerProps {
  /** The selected date (controlled).
   * @default undefined
   */
  value?: Date;
  /** Fires with the new date (or `undefined` when cleared) on selection.
   * @default undefined
   */
  onValueChange?: (date: Date | undefined) => void;
  /**
   * The calendar's open state (controlled). Pair it with `onOpenChange`; omit it and the picker
   * opens and closes itself.
   * @default undefined
   */
  open?: boolean;
  /**
   * Fires when the calendar opens or closes, after the `onValueChange` of the day that closed it
   * (a day picked, a preset chosen), so a host can tell a choice from a dismissal: a press
   * outside, Escape or the trigger pressed again close it with no pick. The second argument is
   * Base UI's event details: the `reason` it changed and the `event` behind it.
   * @default undefined
   */
  onOpenChange?: (
    open: boolean,
    eventDetails?: Parameters<
      NonNullable<React.ComponentProps<typeof Popover>["onOpenChange"]>
    >[1],
  ) => void;
  /**
   * Trigger text shown when no date is selected.
   * @default "Pick a date"
   */
  placeholder?: string;
  /**
   * `Intl.DateTimeFormat` options for the trigger label.
   * @default { year: 'numeric', month: 'short', day: 'numeric' }
   */
  formatOptions?: Intl.DateTimeFormatOptions;
  /** BCP-47 locale for formatting (defaults to `DEFAULT_LOCALE`, `en-US`, so the server and the browser agree).
   * @default undefined
   */
  locale?: string;
  /** Quick-select presets shown in a left rail. Omit for no presets.
   * @default undefined
   */
  presets?: DatePreset[];
  /** Dates to disable, forwarded to the calendar's `disabled` matcher.
   * @default undefined
   */
  disabledDates?: Matcher | Matcher[];
  /**
   * Props forwarded to the inner `Calendar` for DayPicker features such as
   * `timeZone`, `locale`, `footer`, `captionLayout`, `startMonth`,
   * `endMonth`, `labels`, and `formatters`. Selection ownership stays with
   * `DatePicker`, so `mode`, `selected`, `onSelect`, and `disabled` are not
   * accepted here.

   * @default undefined
   */
  calendarProps?: ForwardedCalendarProps;
  /** Disable the whole control.
   * @default undefined
   */
  disabled?: boolean;
  /**
   * Popover side relative to the trigger.
   * @default "bottom"
   */
  side?: React.ComponentProps<typeof PopoverContent>["side"];
  /**
   * Popover alignment relative to the trigger.
   * @default "start"
   */
  align?: React.ComponentProps<typeof PopoverContent>["align"];
  /** Extra classes for the trigger button.
   * @default undefined
   */
  className?: string;
  /** Accessible name for the trigger (recommended when there is no visible label).
   * @default undefined
   */
  "aria-label"?: string;
  /**
   * `id` for the trigger button, so a `FieldLabel htmlFor` (or any `<label for>`) names it and
   * clicking the label opens the picker — the same binding every other form control takes.
   * @default undefined
   */
  id?: string;
  /**
   * Ids of the elements describing the trigger — a `FieldDescription` or `FieldError`.
   * @default undefined
   */
  "aria-describedby"?: string;
  /**
   * Marks the trigger invalid; the outline `Button` shows its destructive border, exactly as an
   * invalid `Input` or `SelectTrigger` does inside a `Field data-invalid`.
   * @default undefined
   */
  "aria-invalid"?: React.AriaAttributes["aria-invalid"];
  /**
   * Trigger height: `sm` (28px) is the inline tier shared with `Select size="sm"` and
   * `SearchableSelect size="sm"`, for table rows and toolbars.
   * @default 'default'
   */
  size?: "sm" | "default";
  /**
   * `ghost` is the inline trigger: content width, no border at rest, the border on hover, on
   * focus and while the calendar is open — the same tier as `Select variant="ghost"`.
   * @default 'outline'
   */
  variant?: "outline" | "ghost";
  /**
   * The trigger sits flat in a surface that is already its box (a grid cell's editor): no border,
   * fill or shadow, and no open tint while the calendar is open. Keyboard focus keeps the global
   * cue. Off, the trigger is unchanged.
   * @default false
   */
  flat?: boolean;
  /**
   * Shows a clear control beside the trigger while a date is set, which reports `undefined`.
   * It is a sibling of the trigger, never inside it, and focus returns to the trigger after
   * clearing.
   * @default false
   */
  clearable?: boolean;
  /**
   * Accessible name for the clear control.
   * @default "Clear date"
   */
  clearLabel?: string;
  /**
   * Renders the selected date on the trigger in place of the formatted date — e.g.
   * `(date) => \`Due ${format(date)}\``.
   * @default undefined
   */
  renderValue?: (date: Date) => React.ReactNode;
  /** Ref forwarded to the trigger button.
   * @default undefined
   */
  ref?: React.Ref<HTMLButtonElement>;
}

/** The inline (`ghost`) trigger chrome shared with `Select variant="ghost"`. */
const GHOST_TRIGGER =
  "border-transparent bg-transparent shadow-none hover:border-input dark:bg-transparent";

/**
 * The `flat` trigger: no border, fill or shadow in any state, and no open layer — for a surface
 * that is already the trigger's box. The same tier as `SearchableSelect flat`. The open layer is
 * removed under `data-flat` too, so it outranks Button's own `aria-expanded:layer-selected`.
 */
const FLAT_TRIGGER =
  "border-transparent bg-transparent shadow-none hover:border-transparent data-flat:aria-expanded:bg-none dark:border-transparent dark:bg-transparent";

/**
 * `DatePicker` — pick a single date. Renders an outline `Button` showing the formatted date (or the
 * placeholder), opening a `Calendar` in a `Popover`. Selecting a day fires `onValueChange` and
 * closes the popover. Add `presets` for a Today / Tomorrow quick rail.
 *
 * @example
 * const [date, setDate] = React.useState<Date>();
 * <DatePicker value={date} onValueChange={setDate} />
 *
 * @example
 * // Inline in a table row: the small ghost tier, clearable, with a custom face
 * <DatePicker
 *   size="sm"
 *   variant="ghost"
 *   clearable
 *   value={due}
 *   onValueChange={setDue}
 *   renderValue={(date) => `Due ${formatShort(date)}`}
 * />
 */
export function DatePicker({
  value,
  onValueChange,
  open: openProp,
  onOpenChange,
  placeholder = "Pick a date",
  formatOptions = DEFAULT_TRIGGER_FORMAT,
  locale,
  presets,
  disabledDates,
  calendarProps,
  disabled,
  side = "bottom",
  align = "start",
  className,
  "aria-label": ariaLabel,
  id,
  "aria-describedby": ariaDescribedBy,
  "aria-invalid": ariaInvalid,
  size = "default",
  variant = "outline",
  flat = false,
  clearable = false,
  clearLabel = "Clear date",
  renderValue,
  ref,
}: DatePickerProps) {
  const [openState, setOpenState] = React.useState(false);
  const open = openProp ?? openState;
  const setOpen: NonNullable<DatePickerProps["onOpenChange"]> = (
    next,
    eventDetails,
  ) => {
    setOpenState(next);
    onOpenChange?.(next, eventDetails);
  };
  const [trigger, setTrigger] = React.useState<HTMLButtonElement | null>(null);
  const triggerRef = React.useMemo(() => mergeRefs(setTrigger, ref), [ref]);
  const showClear = clearable && value !== undefined;
  const ghost = variant === "ghost";
  const {
    defaultMonth,
    autoFocus = true,
    ...calendarRestProps
  } = calendarProps ?? {};
  const today = useZonedToday(open, calendarRestProps);
  const dateFormat = useDateFormat();

  const handleSelect = (date: Date | undefined) => {
    onValueChange?.(date);
    if (date) setOpen(false);
  };

  const picker = (
    <Popover open={open} onOpenChange={setOpen}>
      {/* DS-47: the trigger renders through Base UI `Field.Control`, so inside a `Field` it takes
            its label, description and error ids and `aria-invalid` from the Field. The explicit
            props below still win (`id`) or come first (`aria-describedby`). */}
      <FieldPrimitive.Control
        id={id}
        disabled={disabled}
        aria-describedby={ariaDescribedBy}
        aria-invalid={ariaInvalid}
        render={
          <PopoverTrigger
            render={
              <Button
                ref={triggerRef}
                variant="outline"
                // Fetch the calendar engine as soon as the picker is likely to open.
                onPointerEnter={prefetchCalendar}
                onFocus={prefetchCalendar}
                size={size === "sm" ? "sm" : "default"}
                data-slot="date-picker-trigger"
                data-size={size}
                data-variant={variant}
                data-flat={flat ? "" : undefined}
                data-empty={value ? undefined : ""}
                aria-label={ariaLabel}
                className={cn(
                  // `w-full` like upstream's Input, Select trigger and Combobox trigger — a form
                  // control takes its width from its parent. A fixed-width trigger overflowed a 320px
                  // content area and was the only fixed-width control in the system (audit B8-03).
                  "w-full justify-start gap-2 font-normal data-[empty]:text-muted-foreground",
                  // The `sm` tier keeps 14px text, like `Select size="sm"`.
                  size === "sm" && "text-sm",
                  ghost && GHOST_TRIGGER,
                  flat && FLAT_TRIGGER,
                  // Content width for the inline tier. A clearable picker's wrapper carries the
                  // width instead, and the trigger fills it, so the clear control always sits in
                  // the trigger's own trailing reserve.
                  ghost && !clearable && "w-fit",
                  // The clear control's reserve, so the label does not move when a date is set.
                  clearable && "pe-9",
                  className,
                )}
              >
                <CalendarIcon
                  className="size-4 text-muted-foreground"
                  aria-hidden
                />
                {/* A flex child only truncates with `min-w-0` (LAY-11). */}
                <span className="min-w-0 truncate">
                  {value
                    ? (renderValue?.(value) ??
                      formatDate(value, formatOptions, locale, dateFormat))
                    : placeholder}
                </span>
              </Button>
            }
          />
        }
      />
      <PopoverContent
        data-slot="date-picker-content"
        side={side}
        align={align}
        className={cn(POPUP_CLASSES, presets && "flex-row max-sm:flex-col")}
      >
        <CalendarBody>
          {({ Calendar }) => (
            <>
              {presets ? (
                <PresetRail>
                  {presets.map((preset) => {
                    // Honor the SAME `disabledDates` policy the calendar applies — a preset whose date
                    // is blocked must be inert (disabled UI) and must never emit a value.
                    const presetDisabled = isDateDisabled(
                      preset.date,
                      disabledDates,
                    );
                    return (
                      <Button
                        key={preset.label}
                        variant="ghost"
                        size="sm"
                        disabled={presetDisabled}
                        aria-disabled={presetDisabled || undefined}
                        className="justify-start font-normal"
                        onClick={() => {
                          // Defense in depth: never emit a disabled value even if the click slips through.
                          if (isDateDisabled(preset.date, disabledDates))
                            return;
                          onValueChange?.(preset.date);
                          setOpen(false);
                        }}
                      >
                        {preset.label}
                      </Button>
                    );
                  })}
                </PresetRail>
              ) : null}
              <Calendar
                components={POPOVER_CALENDAR_COMPONENTS}
                {...calendarRestProps}
                className={cn(
                  POPUP_CALENDAR_CLASSES,
                  calendarRestProps.className,
                )}
                today={today}
                mode="single"
                selected={value}
                onSelect={handleSelect}
                defaultMonth={defaultMonth ?? value ?? today}
                disabled={disabledDates}
                autoFocus={autoFocus}
              />
            </>
          )}
        </CalendarBody>
      </PopoverContent>
    </Popover>
  );

  if (!clearable) return picker;

  // DS-22: the clear control is a SIBLING after the trigger — an interactive control may not
  // contain another — sharing the trigger's trailing `pe-9` reserve. It unmounts the moment the
  // date clears, so it hands focus to the trigger first; no announcement, the change is visible.
  return (
    <div
      data-slot="date-picker"
      className={cn("relative min-w-0", ghost ? "w-fit" : "w-full")}
    >
      {picker}
      {showClear ? (
        <Button
          variant="ghost"
          size="icon-xs"
          aria-label={clearLabel}
          disabled={disabled}
          data-slot="date-picker-clear"
          // Centred with auto margins, not `-translate-y-1/2`: Button's press nudge sets `translate-y`
          // and would replace the centring transform, dropping the × by half its height.
          className="absolute inset-y-0 end-1.5 my-auto active:not-aria-[haspopup]:translate-y-0"
          onClick={() => {
            trigger?.focus();
            onValueChange?.(undefined);
          }}
        >
          <X />
        </Button>
      ) : null}
    </div>
  );
}

/* ------------------------------------------------------------------------------------------------
 * DateTimePicker — a date and a time of day, picked in one popup
 * ----------------------------------------------------------------------------------------------*/

/** Every string the date-and-time picker renders or names a part with. */
export interface DateTimePickerLabels {
  /** The typed time field's accessible name. */
  time: string;
  /** The list of times' accessible name. */
  times: string;
  /** The typed field's text while empty. */
  typeTime: string;
}

const DEFAULT_DATE_TIME_LABELS: DateTimePickerLabels = {
  time: "Time",
  times: "Times",
  typeTime: "Type a time",
};

/** Trigger face for a moment: "Nov 3, 2026, 9:00 AM". */
const DEFAULT_DATE_TIME_FORMAT: Intl.DateTimeFormatOptions = {
  year: "numeric",
  month: "short",
  day: "numeric",
  hour: "numeric",
  minute: "2-digit",
};

/** Props accepted by `DateTimePicker`. */
export interface DateTimePickerProps {
  /** The moment (controlled); `undefined` for none.
   * @default undefined
   */
  value?: Date;
  /**
   * Fires with the new moment when a day or a time is picked, and with `undefined` when cleared.
   * @default undefined
   */
  onValueChange?: (value: Date | undefined) => void;
  /**
   * The popup's open state (controlled). Pair it with `onOpenChange`.
   * @default undefined
   */
  open?: boolean;
  /** Fires when the popup opens or closes.
   * @default undefined
   */
  onOpenChange?: (open: boolean) => void;
  /**
   * IANA zone whose calendar and clock the picker shows. Omit it to use the reader's zone from
   * `TimeZoneProvider`, else the runtime's.
   * @default undefined
   */
  timeZone?: string;
  /**
   * The time a day picked on its own takes, `HH:MM` (24-hour).
   * @default "09:00"
   */
  defaultTime?: string;
  /**
   * Minutes between the times in the list. A typed time may fall between them.
   * @default 15
   */
  step?: number;
  /**
   * `h12` ("9:30 AM") or `h23` ("09:30"). Omit it and the locale decides.
   * @default undefined
   */
  hourCycle?: TimeHourCycle;
  /**
   * Trigger text shown when there is no moment.
   * @default "Pick a date and time"
   */
  placeholder?: string;
  /**
   * `Intl.DateTimeFormat` options for the trigger label (formatted in `timeZone`).
   * @default { year: 'numeric', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' }
   */
  formatOptions?: Intl.DateTimeFormatOptions;
  /** BCP-47 locale for the face, the calendar and the clock (defaults to `DEFAULT_LOCALE`).
   * @default undefined
   */
  locale?: string;
  /** Days to disable, forwarded to the calendar's `disabled` matcher.
   * @default undefined
   */
  disabledDates?: Matcher | Matcher[];
  /** Disable the whole control.
   * @default undefined
   */
  disabled?: boolean;
  /**
   * Popover side relative to the trigger.
   * @default "bottom"
   */
  side?: React.ComponentProps<typeof PopoverContent>["side"];
  /**
   * Popover alignment relative to the trigger.
   * @default "start"
   */
  align?: React.ComponentProps<typeof PopoverContent>["align"];
  /** Extra classes for the trigger button.
   * @default undefined
   */
  className?: string;
  /** Accessible name for the trigger (recommended when there is no visible label).
   * @default undefined
   */
  "aria-label"?: string;
  /** `id` for the trigger, so a `FieldLabel htmlFor` names it and opens the picker.
   * @default undefined
   */
  id?: string;
  /** Ids of the elements describing the trigger — a `FieldDescription` or `FieldError`.
   * @default undefined
   */
  "aria-describedby"?: string;
  /** Marks the trigger invalid (the destructive border).
   * @default undefined
   */
  "aria-invalid"?: React.AriaAttributes["aria-invalid"];
  /**
   * Trigger height: `sm` (28px) is the inline tier shared with `DatePicker size="sm"`.
   * @default 'default'
   */
  size?: "sm" | "default";
  /**
   * `ghost` is the inline trigger (a grid cell, a property row): content width, no border at rest.
   * @default 'outline'
   */
  variant?: "outline" | "ghost";
  /**
   * The trigger sits flat in a surface that is already its box (a grid cell's editor): no border,
   * fill or shadow, and no open tint while its popup is open. Keyboard focus keeps the global
   * cue. Off, the trigger is unchanged.
   * @default false
   */
  flat?: boolean;
  /**
   * Shows a clear control beside the trigger while a moment is set, which reports `undefined`.
   * @default false
   */
  clearable?: boolean;
  /**
   * Accessible name for the clear control.
   * @default "Clear date and time"
   */
  clearLabel?: string;
  /** Replace the time column's strings (`DateTimePickerLabels`).
   * @default undefined
   */
  labels?: Partial<DateTimePickerLabels>;
  /** Ref forwarded to the trigger button.
   * @default undefined
   */
  ref?: React.Ref<HTMLButtonElement>;
}

/** Every `step` minutes from midnight, plus `extra` (an off-step value) in its place. */
function timesOfDay(step: number, extra: string | null | undefined) {
  const every = Math.min(720, Math.max(1, Math.round(step)));
  const values = new Set<string>();
  for (let at = 0; at < 24 * 60; at += every)
    values.add(
      `${String(Math.floor(at / 60)).padStart(2, "0")}:${String(at % 60).padStart(2, "0")}`,
    );
  if (extra) values.add(extra);
  return [...values].sort();
}

/**
 * `DateTimePicker` — a date and a time of day in one control. One trigger ("Nov 3, 2026, 9:00
 * AM") opens one popup: the calendar, and beside it the time — a field to type one ("930",
 * "9:30 pm", "21:30") over the day's times every `step` minutes. Picking a day keeps the popup
 * open for the time (a day alone takes `defaultTime`, 09:00); picking or entering a time closes it.
 * The value is an instant, shown and edited on the reader's clock (`timeZone`, else
 * `TimeZoneProvider`): a wall time the zone skips moves past the gap, a repeated one keeps the
 * offset it had.
 *
 * @example
 * const [due, setDue] = React.useState<Date>();
 * <DateTimePicker aria-label="Due" value={due} onValueChange={setDue} clearable />
 *
 * @example
 * // A grid cell: the small inline tier, on a 24-hour clock every 30 minutes
 * <DateTimePicker size="sm" variant="ghost" hourCycle="h23" step={30} value={at} onValueChange={setAt} />
 */
export function DateTimePicker({
  value,
  onValueChange,
  open: openProp,
  onOpenChange,
  timeZone: timeZoneProp,
  defaultTime = "09:00",
  step = 15,
  hourCycle: hourCycleProp,
  placeholder = "Pick a date and time",
  formatOptions = DEFAULT_DATE_TIME_FORMAT,
  locale = DEFAULT_LOCALE,
  disabledDates,
  disabled,
  side = "bottom",
  align = "start",
  className,
  "aria-label": ariaLabel,
  id,
  "aria-describedby": ariaDescribedBy,
  "aria-invalid": ariaInvalid,
  size = "default",
  variant = "outline",
  flat = false,
  clearable = false,
  clearLabel = "Clear date and time",
  labels: labelsProp,
  ref,
}: DateTimePickerProps) {
  const labels = { ...DEFAULT_DATE_TIME_LABELS, ...labelsProp };
  const readerZone = useTimeZone();
  const timeZone = timeZoneProp ?? readerZone;
  const dateFormat = useDateFormat();
  const hourCycle =
    hourCycleProp ?? dateFormat?.hourCycle ?? localeHourCycle(locale);
  const [openState, setOpenState] = React.useState(false);
  const open = openProp ?? openState;
  const setOpen = (next: boolean) => {
    setOpenState(next);
    onOpenChange?.(next);
  };
  const [trigger, setTrigger] = React.useState<HTMLButtonElement | null>(null);
  const triggerRef = React.useMemo(() => mergeRefs(setTrigger, ref), [ref]);
  const ghost = variant === "ghost";

  const valid = value && !Number.isNaN(value.getTime()) ? value : undefined;
  const iso = valid?.toISOString() ?? null;
  const current = iso ? zonedParts(iso, timeZone) : null;
  // One Date per day: a new object each render reads to the calendar as a new selection, and its
  // autofocus pulls focus from the time field to the day.
  const currentDay = current?.day;
  const selectedDay = React.useMemo(
    () => (currentDay ? parseCalendarDay(currentDay) : undefined),
    [currentDay],
  );
  // The grid's "today" is the picker's zone's day (the engine's own when there is no zone).
  const today = React.useMemo(
    () => (open && timeZone ? zonedToday(Date.now(), timeZone) : undefined),
    [open, timeZone],
  );
  const commit = (day: string, time: string) =>
    onValueChange?.(new Date(fromZoned(day, time, timeZone, iso)));
  /** A time picked before any day lands on today, on the picker's clock. */
  const dayForTime = () =>
    current?.day ?? zonedParts(new Date().toISOString(), timeZone).day;

  // The typed field: `null` while it shows the value's own time.
  const [draft, setDraft] = React.useState<string | null>(null);
  const parsed = draft == null ? undefined : parseTimeOfDay(draft, locale);
  const draftInvalid = draft != null && draft.trim() !== "" && !parsed;
  const takeDraft = (close: boolean) => {
    if (draft == null) {
      if (close) setOpen(false);
      return;
    }
    if (parsed) {
      commit(dayForTime(), parsed);
      if (close) setOpen(false);
    }
    setDraft(null);
  };

  const times = React.useMemo(
    () => timesOfDay(step, current?.time),
    [step, current?.time],
  );
  // On open, the list scrolls to the value (else the default time) instead of midnight.
  const scrollToCurrent = React.useCallback(
    (list: HTMLDivElement | null) => {
      if (!list) return;
      const target = current?.time ?? defaultTime;
      const items = Array.from(
        list.querySelectorAll<HTMLElement>("[data-time]"),
      );
      const item =
        items.find((el) => (el.dataset.time ?? "") >= target) ?? items.at(-1);
      // Measured against the list itself: `offsetTop` counts from the popup, which puts the
      // calendar's height above the list once the column stacks under it on a phone.
      if (item) {
        const from = list.getBoundingClientRect();
        const at = item.getBoundingClientRect();
        list.scrollTop +=
          at.top - from.top - list.clientHeight / 2 + at.height / 2;
      }
    },
    [current?.time, defaultTime],
  );

  // The default face under a provider's `dateFormat` reads in the workspace's order:
  // "12 Nov 2026, 15:40".
  const face = valid
    ? dateFormat && formatOptions === DEFAULT_DATE_TIME_FORMAT
      ? formatDateTime(valid, {
          timeZone,
          dateFormat: { ...dateFormat, hourCycle },
          relativeDay: false,
          withYear: true,
          separator: "comma",
        })
      : new Intl.DateTimeFormat(locale, {
          ...formatOptions,
          hourCycle,
          timeZone,
        })
          .format(valid)
          .replace(/[  ]/g, " ")
    : placeholder;

  const picker = (
    <Popover
      open={open}
      onOpenChange={(next) => {
        if (!next) setDraft(null);
        setOpen(next);
      }}
    >
      <FieldPrimitive.Control
        id={id}
        disabled={disabled}
        aria-describedby={ariaDescribedBy}
        aria-invalid={ariaInvalid}
        render={
          <PopoverTrigger
            render={
              <Button
                ref={triggerRef}
                variant="outline"
                onPointerEnter={prefetchCalendar}
                onFocus={prefetchCalendar}
                size={size === "sm" ? "sm" : "default"}
                data-slot="date-time-picker-trigger"
                data-size={size}
                data-variant={variant}
                data-flat={flat ? "" : undefined}
                data-empty={valid ? undefined : ""}
                aria-label={ariaLabel}
                className={cn(
                  "w-full justify-start gap-2 font-normal data-[empty]:text-muted-foreground",
                  size === "sm" && "text-sm",
                  ghost && GHOST_TRIGGER,
                  flat && FLAT_TRIGGER,
                  ghost && !clearable && "w-fit",
                  clearable && "pe-9",
                  className,
                )}
              >
                <CalendarClock
                  className="size-4 text-muted-foreground"
                  aria-hidden
                />
                <span className="min-w-0 truncate">{face}</span>
              </Button>
            }
          />
        }
      />
      <PopoverContent
        data-slot="date-time-picker-content"
        side={side}
        align={align}
        className={cn(POPUP_CLASSES, "flex-row max-sm:flex-col")}
      >
        <CalendarBody>
          {/* The time column comes with the calendar: rendered before it, it took the popup's
              first focus, and the calendar's autofocus then pulled focus out of a typed time. */}
          {({ Calendar }) => (
            <>
              <Calendar
                components={POPOVER_CALENDAR_COMPONENTS}
                className={POPUP_CALENDAR_CLASSES}
                today={today}
                mode="single"
                selected={selectedDay}
                onSelect={(day: Date | undefined) => {
                  // A day keeps the popup open for the time; picking the same day again does nothing.
                  if (day)
                    commit(toCalendarDay(day), current?.time ?? defaultTime);
                }}
                defaultMonth={selectedDay ?? today}
                disabled={disabledDates}
                autoFocus
              />
              <div
                data-slot="date-time-picker-time"
                className="flex w-36 shrink-0 flex-col border-s border-border max-sm:w-auto max-sm:border-s-0 max-sm:border-t"
              >
                <div className="p-2 pb-1">
                  <Input
                    size="sm"
                    aria-label={labels.time}
                    placeholder={labels.typeTime}
                    autoComplete="off"
                    value={
                      draft ??
                      (current
                        ? formatTimeValue(current.time, locale, hourCycle)
                        : "")
                    }
                    aria-invalid={draftInvalid || undefined}
                    className="tabular-nums"
                    onChange={(event) => setDraft(event.target.value)}
                    onBlur={() => takeDraft(false)}
                    onKeyDown={(event) => {
                      if (event.key === "Enter") {
                        event.preventDefault();
                        takeDraft(true);
                      } else if (event.key === "Escape" && draft != null) {
                        // The first Escape only drops what was typed; the next closes the popup.
                        event.preventDefault();
                        event.stopPropagation();
                        setDraft(null);
                      }
                    }}
                  />
                </div>
                <div
                  ref={scrollToCurrent}
                  data-slot="date-time-picker-times"
                  className="h-64 overflow-y-auto overscroll-contain p-1 pt-0 max-sm:h-40"
                >
                  <ToggleGroup
                    aria-label={labels.times}
                    orientation="vertical"
                    spacing={0.5}
                    deselectable={false}
                    className="w-full"
                    value={current ? [current.time] : []}
                    onValueChange={(next: string[]) => {
                      const time = next[0];
                      if (!time) return;
                      setDraft(null);
                      commit(dayForTime(), time);
                      setOpen(false);
                    }}
                  >
                    {times.map((time) => (
                      <ToggleGroupItem
                        key={time}
                        value={time}
                        data-time={time}
                        // The chosen time reads like a chosen `SelectItem`: no fill, a trailing
                        // check. Hover and focus keep the toggle's own state tint.
                        className="justify-between px-2 font-normal tabular-nums aria-pressed:bg-transparent"
                      >
                        {formatTimeValue(time, locale, hourCycle)}
                        <CheckIcon
                          aria-hidden="true"
                          data-slot="date-time-picker-time-check"
                          className="invisible group-aria-pressed/toggle:visible"
                        />
                      </ToggleGroupItem>
                    ))}
                  </ToggleGroup>
                </div>
              </div>
            </>
          )}
        </CalendarBody>
      </PopoverContent>
    </Popover>
  );

  if (!clearable) return picker;

  return (
    <div
      data-slot="date-time-picker"
      className={cn("relative min-w-0", ghost ? "w-fit" : "w-full")}
    >
      {picker}
      {valid ? (
        <Button
          variant="ghost"
          size="icon-xs"
          aria-label={clearLabel}
          disabled={disabled}
          data-slot="date-time-picker-clear"
          className="absolute inset-y-0 end-1.5 my-auto active:not-aria-[haspopup]:translate-y-0"
          onClick={() => {
            trigger?.focus();
            onValueChange?.(undefined);
          }}
        >
          <X />
        </Button>
      ) : null}
    </div>
  );
}

/* ------------------------------------------------------------------------------------------------
 * DateRangePicker
 * ----------------------------------------------------------------------------------------------*/

/** Props accepted by `DateRangePicker`. */
export interface DateRangePickerProps {
  /** The selected range (controlled).
   * @default undefined
   */
  value?: DateRange;
  /** Fires with the new range (or `undefined` when cleared) on selection.
   * @default undefined
   */
  onValueChange?: (range: DateRange | undefined) => void;
  /**
   * Trigger text shown when no range is selected.
   * @default "Pick a date range"
   */
  placeholder?: string;
  /**
   * `Intl.DateTimeFormat` options for each end of the trigger label.
   * @default { year: 'numeric', month: 'short', day: 'numeric' }
   */
  formatOptions?: Intl.DateTimeFormatOptions;
  /** BCP-47 locale for formatting (defaults to `DEFAULT_LOCALE`, `en-US`, so the server and the browser agree).
   * @default undefined
   */
  locale?: string;
  /** Quick-select presets shown in a left rail. Omit for no presets.
   * @default undefined
   */
  presets?: DateRangePreset[];
  /** Dates to disable, forwarded to the calendar's `disabled` matcher.
   * @default undefined
   */
  disabledDates?: Matcher | Matcher[];
  /**
   * Props forwarded to the inner `Calendar` for DayPicker features such as
   * `timeZone`, `locale`, `footer`, `captionLayout`, `startMonth`,
   * `endMonth`, `labels`, and `formatters`. Selection ownership stays with
   * `DateRangePicker`, so `mode`, `selected`, `onSelect`, and `disabled` are
   * not accepted here.

   * @default undefined
   */
  calendarProps?: ForwardedCalendarProps;
  /** Disable the whole control.
   * @default undefined
   */
  disabled?: boolean;
  /**
   * Number of month grids to show side by side.
   * @default 2
   */
  numberOfMonths?: number;
  /**
   * Popover side relative to the trigger.
   * @default "bottom"
   */
  side?: React.ComponentProps<typeof PopoverContent>["side"];
  /**
   * Popover alignment relative to the trigger.
   * @default "start"
   */
  align?: React.ComponentProps<typeof PopoverContent>["align"];
  /** Extra classes for the trigger button.
   * @default undefined
   */
  className?: string;
  /** Accessible name for the trigger (recommended when there is no visible label).
   * @default undefined
   */
  "aria-label"?: string;
  /**
   * `id` for the trigger button, so a `FieldLabel htmlFor` (or any `<label for>`) names it and
   * clicking the label opens the picker — the same binding every other form control takes.
   * @default undefined
   */
  id?: string;
  /**
   * Ids of the elements describing the trigger — a `FieldDescription` or `FieldError`.
   * @default undefined
   */
  "aria-describedby"?: string;
  /**
   * Marks the trigger invalid; the outline `Button` shows its destructive border, exactly as an
   * invalid `Input` or `SelectTrigger` does inside a `Field data-invalid`.
   * @default undefined
   */
  "aria-invalid"?: React.AriaAttributes["aria-invalid"];
}

/**
 * `DateRangePicker` — pick a `{ from, to }` range across two months. Same shape as `DatePicker`:
 * an outline `Button` shows the formatted range and opens a two-month `Calendar` in a `Popover`.
 * The popover stays open until both ends are chosen. Add `presets` for Last 7 / Last 30 day rails.
 *
 * @example
 * const [range, setRange] = React.useState<DateRange>();
 * <DateRangePicker value={range} onValueChange={setRange} />
 */
export function DateRangePicker({
  value,
  onValueChange,
  placeholder = "Pick a date range",
  formatOptions = DEFAULT_TRIGGER_FORMAT,
  locale,
  presets,
  disabledDates,
  calendarProps,
  disabled,
  numberOfMonths,
  side = "bottom",
  align = "start",
  className,
  "aria-label": ariaLabel,
  id,
  "aria-describedby": ariaDescribedBy,
  "aria-invalid": ariaInvalid,
}: DateRangePickerProps) {
  const [open, setOpen] = React.useState(false);
  // react-day-picker may emit a same-day COMPLETE range on the first click. Closing from that
  // shape makes a two-endpoint gesture impossible, especially when replacing an existing range.
  // Track the current popover session explicitly and normalize its first day to an open range.
  const rangeSelectionStartedRef = React.useRef(false);
  const {
    defaultMonth,
    numberOfMonths: calendarNumberOfMonths,
    autoFocus = true,
    ...calendarRestProps
  } = calendarProps ?? {};
  const today = useZonedToday(open, calendarRestProps);
  const dateFormat = useDateFormat();

  const handleOpenChange = (nextOpen: boolean) => {
    rangeSelectionStartedRef.current = false;
    setOpen(nextOpen);
  };

  const handleSelect = (range: DateRange | undefined, triggerDate: Date) => {
    if (!rangeSelectionStartedRef.current) {
      rangeSelectionStartedRef.current = true;
      onValueChange?.({ from: triggerDate, to: undefined });
      return;
    }

    onValueChange?.(range);
    // Close only after the SECOND endpoint gesture produces a complete range.
    if (range?.from && range.to) setOpen(false);
  };

  const label = value?.from
    ? formatRange(value, formatOptions, locale, dateFormat)
    : placeholder;

  return (
    <Popover open={open} onOpenChange={handleOpenChange}>
      {/* DS-47: the trigger renders through Base UI `Field.Control`, so inside a `Field` it takes
          its label, description and error ids and `aria-invalid` from the Field. The explicit
          props below still win (`id`) or come first (`aria-describedby`). */}
      <FieldPrimitive.Control
        id={id}
        disabled={disabled}
        aria-describedby={ariaDescribedBy}
        aria-invalid={ariaInvalid}
        render={
          <PopoverTrigger
            render={
              <Button
                variant="outline"
                onPointerEnter={prefetchCalendar}
                onFocus={prefetchCalendar}
                data-slot="date-range-picker-trigger"
                data-empty={value?.from ? undefined : ""}
                aria-label={ariaLabel}
                className={cn(
                  // `w-full` — see the single DatePicker's note above (audit B8-03).
                  "w-full justify-start gap-2 font-normal data-[empty]:text-muted-foreground",
                  className,
                )}
              >
                <CalendarIcon
                  className="size-4 text-muted-foreground"
                  aria-hidden
                />
                <span className="min-w-0 truncate">{label}</span>
              </Button>
            }
          />
        }
      />
      <PopoverContent
        data-slot="date-range-picker-content"
        side={side}
        align={align}
        className={cn(POPUP_CLASSES, presets && "flex-row max-sm:flex-col")}
      >
        <CalendarBody>
          {({ Calendar }) => (
            <>
              {presets ? (
                <PresetRail>
                  {presets.map((preset) => {
                    // A range preset is blocked when ANY day it spans (endpoints + every day between) is
                    // disabled — same matcher the calendar uses, so the gate can't drift.
                    const presetDisabled = isRangeDisabled(
                      preset.range,
                      disabledDates,
                    );
                    return (
                      <Button
                        key={preset.label}
                        variant="ghost"
                        size="sm"
                        disabled={presetDisabled}
                        aria-disabled={presetDisabled || undefined}
                        className="justify-start font-normal"
                        onClick={() => {
                          // Defense in depth: never emit a range that intersects disabled dates.
                          if (isRangeDisabled(preset.range, disabledDates))
                            return;
                          onValueChange?.(preset.range);
                          setOpen(false);
                        }}
                      >
                        {preset.label}
                      </Button>
                    );
                  })}
                </PresetRail>
              ) : null}
              <Calendar
                components={POPOVER_CALENDAR_COMPONENTS}
                {...calendarRestProps}
                className={cn(
                  POPUP_CALENDAR_CLASSES,
                  calendarRestProps.className,
                )}
                today={today}
                mode="range"
                selected={value}
                onSelect={handleSelect}
                defaultMonth={defaultMonth ?? value?.from ?? today}
                numberOfMonths={numberOfMonths ?? calendarNumberOfMonths ?? 2}
                disabled={disabledDates}
                autoFocus={autoFocus}
              />
            </>
          )}
        </CalendarBody>
      </PopoverContent>
    </Popover>
  );
}

export type { DateRange, Matcher } from "react-day-picker";
